import java.util.*;

class Solution {
  public long maximumSumOfHeights(List<Integer> maxHeights) {
    int n = maxHeights.size();
    long[] left = new long[n], right = new long[n];
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
      while (!st.isEmpty() && maxHeights.get(st.peek()) > maxHeights.get(i)) st.pop();
      int p = st.isEmpty() ? -1 : st.peek();
      left[i] = (p < 0 ? 0 : left[p]) + (long) (i - p) * maxHeights.get(i);
      st.push(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; i--) {
      while (!st.isEmpty() && maxHeights.get(st.peek()) > maxHeights.get(i)) st.pop();
      int p = st.isEmpty() ? n : st.peek();
      right[i] = (p == n ? 0 : right[p]) + (long) (p - i) * maxHeights.get(i);
      st.push(i);
    }
    long ans = 0;
    for (int i = 0; i < n; i++) ans = Math.max(ans, left[i] + right[i] - maxHeights.get(i));
    return ans;
  }
}
